type BrainCompilerOmission = {
  candidateId: string;
  reason: string;
  estimatedBytes: number | null;
};

type BrainCompilerStop = {
  reason: string;
  sufficient: boolean;
  detail: string;
};

type BrainCompilerReporting = {
  omissions: { total: number; returned: number };
  diagnostics: { total: number; returned: number };
};

type BrainCompilerDiagnostic = {
  code: string;
  message: string;
  provider: string | null;
  details: Record<string, unknown>;
};

function compilerHasUnavailableEvidence(diagnostics: BrainRetrievalResult["diagnostics"]): boolean {
  return diagnostics.some(({ code }) =>
    ["SOURCE_PATH_INVALID", "SOURCE_NOT_FOUND", "SOURCE_NOT_TEXT", "PROVIDER_FAILED"].includes(code) ||
    (code.startsWith("LOCI_") &&
      /(?:FAILED|TIMEOUT|UNAVAILABLE|CONFIG_MISSING|NOT_INDEXED|RESULT_INVALID|RESULT_OUT_OF_SCOPE)$/.test(code)),
  );
}

